# Import of required libraries
import skyramp
import json
import os


# URL for test requests
URL = skyramp.get_base_url("SKYRAMP_TEST_BASE_URL", "http://localhost:9000")

# contract test for /api/recipes GET
def test_recipes_get():
    # Invocation of Skyramp Client
    client = skyramp.Client()
    # Definition of authentication header
    headers = {}
    if os.getenv("SKYRAMP_TEST_TOKEN") is not None:
        headers["Authorization"] = "Bearer " + os.getenv("SKYRAMP_TEST_TOKEN")

    # Expected Response Body
    # items is validated element-by-element below, so it is left out of the schema
    # example: the listing is legitimately empty on a fresh database and non-empty
    # once recipes carry categories, and one example body cannot describe both.
    expected_recipes_GET_response_body = r'''{
        "next": null,
        "page": 1,
        "per_page": 100,
        "previous": null,
        "total": 0,
        "total_pages": 0
    }'''

    # Execute Request
    recipes_GET_response = client.send_request(
        url=URL,
        path="/api/recipes",
        method="GET",
        headers=headers,
        query_params={
            "categories_only": "true",
            "page": "1",
            "perPage": "100"
        }
    )

    # Generated Assertions
    assert recipes_GET_response.status_code == 200
    assert skyramp.check_schema(recipes_GET_response, expected_recipes_GET_response_body)

    body = json.loads(recipes_GET_response.response_body)

    # every PaginationBase key is present, including the nullable guides
    for key in ("page", "per_page", "total", "total_pages", "items", "next", "previous"):
        assert key in body, "GET /api/recipes?categories_only=true dropped the " + key + " key"

    # the response echoes the pagination parameters that were sent
    assert body["page"] == 1
    assert body["per_page"] == 100
    assert isinstance(body["items"], list)
    assert len(body["items"]) <= 100

    # page 1 of a fresh listing has no previous page
    assert body["previous"] is None

    # every recipe the filter returns is a well-formed summary carrying at least one category
    for item in body["items"]:
        for key in ("id", "slug", "name", "recipeCategory"):
            assert key in item, "recipe summary is missing the " + key + " key"
        assert isinstance(item["recipeCategory"], list)
        assert item["recipeCategory"], (
            "categories_only=true returned recipe " + item["slug"] + " with no category"
        )
        for category in item["recipeCategory"]:
            assert category["id"] and category["name"] and category["slug"]

    # total counts every match, so it is never smaller than what this page holds
    assert body["total"] >= len(body["items"]), (
        "total is smaller than the number of items returned on this page"
    )
    # and total_pages follows from total and per_page
    assert body["total_pages"] == -(-body["total"] // body["per_page"]), (
        "total_pages is inconsistent with total/per_page"
    )
    # with per_page=100 the whole result set fits on one page, so there is no next
    assert body["next"] is None, (
        "next advertises a further page although total fits on this one"
    )


if __name__ == "__main__":
    test_recipes_get()
